size_t max_evicts = ckh->max_evicts;
size_t nbuckets = ckh->nbuckets;
size_t bucket = argbucket;
const void *cur_key = argkey;
const void *cur_data = argdata;

for (size_t i = 0; i < max_evicts; ++i) {
    if (ckh->buckets[bucket].key == nullptr) {
        ckh->buckets[bucket].key = const_cast<void *>(cur_key);
        ckh->buckets[bucket].data = const_cast<void *>(cur_data);
        return false;
    }

    const void *evicted_key = ckh->buckets[bucket].key;
    const void *evicted_data = ckh->buckets[bucket].data;

    ckh->buckets[bucket].key = const_cast<void *>(cur_key);
    ckh->buckets[bucket].data = const_cast<void *>(cur_data);

    cur_key = evicted_key;
    cur_data = evicted_data;

    std::size_t h = ckh->hash(cur_key);
    bucket = (bucket ^ h) % nbuckets;
}
return true;

